sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
  initialize: function() {
    // ניתן לשים כאן משתנים משותפים אם צריך
  },

  isDatePast: function(strDate){
    var rightnow = new GlideDateTime();
    var testdate = new GlideDateTime(strDate);

    return testdate.before(rightnow);
  },

  isDateToday: function(strDate){
    var testDate = new GlideDateTime(strDate);
    var now = new GlideDateTime();

    // מביא רק את התאריך (בלי שעה) בפורמט yyyy-MM-dd
    var testDateStr = testDate.getDate().toString();
    var nowStr = now.getDate().toString();

    return testDateStr === nowStr;
  },

  type: 'NeedItUtils'
};
